-- 367K links between bills and the members of Congress who cosponsored them.
-- Auto-generated by scripts/gen_evidence_pages.py: 367,735 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("SPONSORSHIP_DATE") as year, count(*) as records
from THE_LIBRARY.GOVERNMENT.BILL_COSPONSORS
where "SPONSORSHIP_DATE" is not null
group by 1
order by 1
